gKm(){return"\u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u06ce\u0646 \u0644\u0642\u06cc"},
gKn(){return"\u0646\u0627\u06a4\u06ce \u0644\u0642\u06cc"},
Cv(a){return"\u0646\u0631\u062e\u06ce \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646\u06ce \u2014 1 \u062f\u06c6\u0644\u0627\u0631 \u062f\u06a9\u06d5\u062a\u06d5 \u0686\u06d5\u0646\u062f "+a},
