ga1G(){return"\u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06ce\u0646 \u0646\u06d5\u062e\u06c6\u0634\u0627\u0646 \u062f\u06cc\u0627\u0631\u0646"},
ga17(){return"\u062a\u0627\u0628\u0627 \u0648\u06ce\u0646\u06d5\u06af\u0631\u062a\u0646\u06ce \u062f\u06cc\u0627\u0631\u06d5"},
ga1q(){return"\u062f\u0634\u06ce\u062a \u0632\u0627\u0646\u06cc\u0627\u0631\u06cc\u06cc\u06ce\u0646 \u0646\u06d5\u062e\u06c6\u0634\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc \u0628\u06a9\u06d5\u062a"},
