gPB(){return"\u0648\u06d5\u06a9 \u0631\u06c6\u0698\u06ce\u0646 \u06a9\u0627\u0631\u06a9\u0631\u0646\u06ce \u0646\u0627\u0647\u06ce\u0646\u06d5 \u0647\u0698\u0645\u0627\u0631\u062a\u0646\u060c \u0648 \u0626\u0627\u06af\u06d5\u0647\u062f\u0627\u0631\u06cc \u062f\u06cc\u0627\u0631 \u062f\u0628\u06cc\u062a \u062f\u06d5\u0645\u06ce \u0646\u06d5\u0647\u0627\u062a\u0646\u06d5\u06a9 \u062f\u06a9\u06d5\u06a4\u06cc\u062a\u06d5 \u0633\u06d5\u0631 \u0648\u0627\u0646. \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646 \u0644 \u0633\u06d5\u0631 \u0647\u06d5\u06cc\u06a4\u06ce\u0646 \u0646\u0648\u06cc \u06cc\u06ce\u0646 \u0645\u0648\u0648\u0686\u06d5\u06cc \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a\u060c \u0648 \u0644 \u0633\u06d5\u0631 \u0647\u06d5\u06cc\u06a4\u06d5\u06a9\u0627 \u0647\u06d5\u06cc \u062c\u0627\u0631\u0627 \u062f\u0627\u0647\u0627\u062a\u06cc \u062f\u06d5\u0645\u06ce \u0646\u06d5\u0647\u0627\u062a\u0646\u06d5\u06a9 \u062a\u06ce\u062f\u0627 \u062f\u0647\u06ce\u062a\u06d5 \u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646 \u06cc\u0627\u0646 \u0644\u0627\u062f\u0627\u0646."},
Cl(a,b){return"\u0646\u06d5\u0647\u0627\u062a\u0646: "+a+" \u0631\u06c6\u0698 \xb7 \u2212"+b},
gSK(){return"\u0647\u0627\u062a\u06d5 \u0644\u0627\u062f\u0627\u0646 \u2014 \u062f \u062f\u06d5\u0645\u06ce \u062e\u06c6\u062f\u0627 \u0646\u06d5\u0647\u0627\u062a\u06d5 \u06a4\u06d5\u06a9\u0631\u0646"},
a0k(a){return a+" \u0628 \u062a\u06d5\u0645\u0627\u0645\u06cc \u0698\u06ce\u0628\u0628\u06d5\u06cc\u061f"},
vp(a,b,c,d){return"\u0626\u06d5\u06a4\u06d5 \u062a\u06c6\u0645\u0627\u0631\u0627 \u0646\u06d5\u062e\u06c6\u0634\u06cc \u0628 \u062a\u06d5\u0645\u0627\u0645\u06cc \u0698\u06ce\u062f\u0628\u06d5\u062a \u062f\u06af\u06d5\u0644 "+a+" \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc \u0648 "+b+" \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646 \u0648 "+c+" \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0648 "+d+" \u0641\u0627\u06cc\u0644\u060c \u0647\u06d5\u0631\u0648\u06d5\u0633\u0627 \u0631\u06d5\u0686\u06d5\u062a\u06d5 \u0648 \u062a\u06c6\u0645\u0627\u0631\u0627 \u067e\u0632\u06cc\u0634\u06a9\u06cc \u0648 \u067e\u0644\u0627\u0646\u06ce\u0646 \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u06ce \u0648 \u062f\u06cc\u0631\u06c6\u06a9\u0627 \u0698\u06cc\u0631\u06cc\u0627 \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f. \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0698 \u062d\u0633\u06ce\u0628\u0627\u0646 \u062f\u0647\u06ce\u0646\u06d5 \u0631\u0627\u06a9\u0631\u0646 \u0648 \u0642\u0627\u0632\u0627\u0646\u062c\u06ce \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646 \u0698\u06ce \u062f\u0632\u06a4\u0695\u06cc\u062a\u06d5\u06a4\u06d5. \u0626\u06d5\u06a4\u06d5 \u0646\u06d5\u0634\u06ce\u062a \u0628\u0632\u06a4\u0695\u06cc\u062a\u06d5\u06a4\u06d5."},
a0m(a){return"\u0628\u06c6 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u0646\u06ce \xab"+a+"\xbb \u0628\u0646\u06a4\u06ce\u0633\u06d5"},
