gLi(){return"\u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u0627 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u06ce"},
gLk(){return"\u0626\u06d5\u0648\u0627 \u0641\u06c6\u0631\u0645\u06ce \u0633\u0627\u062f\u06d5\u06cc\u06ce \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u0627 \u0633\u06a9\u0631\u062a\u06ce\u0631\u06cc \u062a\u06c6\u0645\u0627\u0631 \u062f\u06a9\u06d5\u062a\u060c \u0648\u06d5\u06a9 \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u0646\u0627 \u0646\u06d5\u062e\u06c6\u0634\u06cc\u06ce. \u062f\u06a9\u062a\u06c6\u0631 \u067e\u0627\u0634\u06cc \u062f\u06af\u06c6\u0647\u0648\u0695\u06cc\u062a \u0628\u06c6 \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u0627 \u0631\u0627\u0633\u062a\u06d5\u0642\u06cc\u0646\u06d5. \u0628\u062a\u0646\u06ce \u0628\u06c6 \u0648\u0627\u0646 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5 \u06cc\u06ce\u0646 \u0645\u06c6\u06b5\u06d5\u062a\u0627 \xab\u0641\u06c6\u0631\u0645\u06ce \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u0627 \u0633\u0627\u062f\u06d5\xbb \u0647\u06d5\u06cc."},
gLj(){return"\u0698\u06ce\u0628\u0631\u0646"},
Y_(a){return"\u0648\u06d5\u06a9 \xab"+a+"\xbb \u0647\u0627\u062a\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646 - \u062f\u06a9\u062a\u06c6\u0631 \u067e\u0627\u0634\u06cc \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u0627 \u0631\u0627\u0633\u062a\u06d5\u0642\u06cc\u0646\u06d5 \u062f\u06cc\u0627\u0631 \u062f\u06a9\u06d5\u062a."},
ga0h(){return"\u06af\u0648\u0647\u0648\u0631\u06cc\u0646\u0627 \u062c\u06c6\u0631\u06ce \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u06ce"},
ga0g(){return"\u06af\u0648\u0647\u0648\u0631\u06cc\u0646\u0627 \u062c\u06c6\u0631\u06ce \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u06ce"},
ga0f(){return"\u0628\u0647\u0627\u06cc\u06ce \u06a4\u06cc\u0632\u06cc\u062a\u0627 \u0626\u06ce\u06a9\u06ce \u0644 \u062f\u0648\u06cc\u0641 \u062c\u06c6\u0631\u06ce \u0646\u0648\u06cc \u062f\u0647\u06ce\u062a\u06d5 \u06af\u0648\u0647\u0648\u0631\u06cc\u0646. \u067e\u0634\u062a\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0644 \u0633\u06d5\u0631 \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u06ce \u0647\u06d5\u0628\u0646 \u0646\u0627\u0647\u06ce\u062a\u06d5 \u06a9\u0631\u0646."},
ga0e(){return"\u062c\u06c6\u0631\u06ce \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u06ce \u0647\u0627\u062a\u06d5 \u06af\u0648\u0647\u0648\u0631\u06cc\u0646"},
gQv(){return"\u06af\u0648\u0647\u0648\u0631\u06cc\u0646\u0627 \u062c\u06c6\u0631\u06ce \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u06ce"},
Zk(a){return"\u0647\u06d5\u0645\u06cc\u0627\u0646 \u0646\u06cc\u0634\u0627\u0646 \u0628\u062f\u06d5 ("+a+")"},
