ga0n(){return"\u0632\u0627\u0646\u06cc\u0627\u0631\u06cc\u06cc\u06ce\u0646 \u0646\u06d5\u062e\u06c6\u0634\u06cc \u0647\u0627\u062a\u0646\u06d5 \u0646\u0648\u06cc\u06a9\u0631\u0646"},
gXv(){return"\u0628 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06ce \u0626\u06c6\u062a\u06c6\u0645\u0627\u062a\u06cc\u06a9 \u06a4\u06cc\u0632\u06cc\u062a\u0627 \u067e\u0634\u06a9\u0646\u06cc\u0646\u0627 \u0626\u06d5\u06a4\u0631\u06c6 \u0628\u06c6 \u06a4\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06cc \u062f\u0647\u06ce\u062a\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646."},
ga0i(){return"\u0646\u06d5\u062e\u06c6\u0634 \u0647\u0627\u062a\u06d5 \u0698\u06ce\u0628\u0631\u0646"},
a0j(a){return"\u0646\u06d5\u062e\u06c6\u0634 \u0647\u0627\u062a\u06d5 \u0698\u06ce\u0628\u0631\u0646\u060c \u0644\u06ce \u0646\u06d5\u0647\u0627\u062a\u06d5 \u06a9\u0631\u0646 "+a+" \u0641\u0627\u06cc\u0644\u06ce\u0646 \u0647\u06d5\u0644\u06af\u0631\u062a\u06cc \u0698\u06ce\u0628\u0628\u06d5\u06cc\u0646."},
gIm(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u06ce\u0646 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce / \u0648\u0627\u062a\u0633\u0627\u0628\u06ce"},
ga3y(){return"\u0626\u06d5\u0648 \u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u0628 \u0631\u06ce\u06a9\u0627 \u0628\u06c6\u062a\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u06cc\u0627\u0646 \u0648\u0627\u062a\u0633\u0627\u0628\u0627 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u062e\u06c6 \u062a\u06c6\u0645\u0627\u0631 \u06a9\u0631\u06cc\u0646. \u0648\u06d5\u06a9\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u0646\u0648\u0648 \u0632\u06ce\u062f\u06d5 \u0628\u06a9\u06d5\u060c \u06cc\u0627\u0646 \u0628 \u0641\u0627\u06cc\u0644\u06d5\u06a9\u0627 \u0647\u06d5\u06cc \u06a4\u06d5 \u06af\u0631\u06ce\u0628\u062f\u06d5\u060c \u06cc\u0627\u0646 \u0631\u06d5\u062a \u0628\u06a9\u06d5. \u062f \u0647\u06d5\u0631\u062f\u0648\u0648 \u062d\u0627\u0644\u06d5\u062a\u0627\u0646 \u062f\u0627 \u0646\u0627\u0645\u06d5\u06cc\u06d5\u06a9 \u062f\u06ce \u0628\u06c6 \u0648\u0627\u0646 \u0686\u06cc\u062a."},
ga3x(){return"\u0686 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646 \u0686\u0627\u06a4\u06d5\u0695\u06ce \u0646\u06cc\u0646\u0646."},
rV(a){return"\u0646\u06d5\u0647\u0627\u062a\u06d5 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646: "+a},
a3t(a){return"\u0628 "+a+" \u06a4\u06d5 \u0647\u0627\u062a\u06d5 \u06af\u0631\u06ce\u062f\u0627\u0646"},
a3q(a){return a+" \u0648\u06d5\u06a9\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u0647\u0627\u062a\u06d5 \u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646"},
ga3w(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646 \u0647\u0627\u062a\u06d5 \u0631\u06d5\u062a\u06a9\u0631\u0646"},
ga3u(){return"\u0646\u06ce\u0631"},
ga3r(){return"\u0645\u06ce"},
ga3p(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646 \u0648\u06d5\u06a9\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06ce \u0646\u0648\u0648"},
ga3s(){return"\u06af\u0631\u06ce\u062f\u0627\u0646 \u0628 \u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u06ce \u0647\u06d5\u06cc"},
ga3v(){return"\u0631\u06d5\u062a\u06a9\u0631\u0646"},
gTP(){return"\u0628\u06c6\u062a\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u0628\u06c6 \u0646\u06d5\u062e\u06c6\u0634\u0627\u0646"},
gTL(){return"\u0628\u06c6\u062a\u06d5\u06a9\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u06cc\u06ce \u062a\u0627\u06cc\u0628\u06d5\u062a \u0628 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u0627 \u062a\u06d5: \u0695\u06c6\u0698\u06d5\u06a9\u06ce \u0628\u06d5\u0631\u06cc \u0647\u06d5\u0631 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u06ce \u0646\u0627\u0645\u06d5\u06cc\u0627 \u0628\u06cc\u0631\u0626\u06cc\u0646\u0627\u0646\u06ce \u0628\u06c6 \u0646\u06d5\u062e\u06c6\u0634\u0627\u0646 \u062f\u0647\u06ce\u062a\u060c \u062f\u0634\u06ce\u0646 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06ce\u0646 \u0628\u06ce\u0646 \u0648 \u0642\u06d5\u0631\u0632\u0627 \u062e\u06c6 \u0628\u0628\u06cc\u0646\u0646\u060c \u0648 \u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u0646\u0648\u0648 \u062f\u0634\u06ce\u0646 \u062e\u06c6 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u06d5\u0646 (\u062a\u0648 \u067e\u0634\u062a\u0695\u0627\u0633\u062a \u062f\u06a9\u06d5\u06cc). \u06a9\u0627\u0631\u067e\u06ce\u06a9\u0631\u0646\u0627 \u0648\u06cc \u0628\u06ce \u0628\u06d5\u0631\u0627\u0645\u0628\u06d5\u0631\u06d5."},
gF4(){return"\u06af\u0631\u06ce\u062f\u0627\u0646\u0627 \u0628\u06c6\u062a\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce"},
